        "osmolality": "non-ionic, low-osmolar (695 mOsm/kg)",
        "iodineContent": "350 mg/mL",
        "viscosity": "low",
        "stability": "stable",
        "dmsoCompatibility": true,
        "deviceMaterialCompatibility": {
          "silicone": true,
          "ptfe": true,
          "polyurethane": true,
          "nitinol": true,
          "platinum": true
        },
        "volumeRecommendations": {
          "diagnosticAngio": "30-50 mL",
          "intracranialThrombectomy": "80-120 mL",
          "embolization": "100-150 mL"
        },
        "notes": "Relatively new non-ionic agent; good safety profile",
        "heatingRequired": false,
        "flushVolume_ml": 5,
