        "dmsoCompatibility": true,
        "deviceMaterialCompatibility": {
          "silicone": true,
          "ptfe": true,
          "polyurethane": false,
          "nitinol": true,
          "platinum": true
        },
        "volumeRecommendations": {
          "diagnosticAngio": "20-30 mL",
          "intracranialThrombectomy": "50-80 mL",
          "embolization": "60-100 mL"
        },
        "notes": "High-osmolar ionic agent; deprecated in many centers due to osmotic complications",
