    "liquidEmbolics": [
      {
        "name": "NBCA (n-butyl cyanoacrylate)",
        "brandNames": [
          "Trufill",
          "Histoacryl"
        ],
        "viscosity": "variable (1-20 cP depending on dilution)",
        "dmsoCompatibility": false,
        "contrastMixing": "must mix with contrast for visibility",
        "recommendedCatheterMaterial": [
          "PTFE",
          "silicone"
        ],
        "avoidMaterials": [
          "some polyurethanes"
        ],
        "preparationNotes": [
          "Mix 1:3 to 1:5 NBCA:lipiodol for visualization",
          "Use non-siliconized syringes (silicon impairs polymerization)",
          "Prepare immediately before injection"
        ],
        "polymerizationTime": "6-10 seconds",
        "injectionPressure_psi": 60,
        "notes": "Immediate polymerization - cannot use DMSO for washout"
      },
      {
        "name": "Onyx (EVOH copolymer in DMSO)",
        "brandNames": [
          "Onyx-18",
          "Onyx-34",
          "Onyx LES"
        ],
        "viscosity": "suspended microspheres in DMSO (high)",
        "dmsoCompatibility": true,
        "contrastMixing": "tantalum powder mixed in for radio-opacity",
        "recommendedCatheterMaterial": [
          "PTFE",
          "silicone"
        ],
        "avoidMaterials": [
          "polyurethane (DMSO degrades it)"
        ],
        "preparationNotes": [
          "DMSO-compatible devices MANDATORY throughout stack",
          "Allow DMSO to penetrate catheter for 5min before injection",
          "Flush lines with normal saline only - NO heparinized flush",
          "Inject slowly over 1-5 min depending on lesion"
        ],
        "polymerizationTime": "10-30 minutes (gradual)",
        "injectionPressure_psi": 40,
        "notes": "Onyx-18 lower viscosity for small vessels; Onyx-34 higher viscosity"
      },
      {
        "name": "Precipitating HEMA",
        "brandNames": [
          "Precipitating Hydrophilic Monomer"
        ],
        "viscosity": "liquid monomer",
        "dmsoCompatibility": true,
        "contrastMixing": "tantalum oxide or iodized oil",
        "recommendedCatheterMaterial": [
          "PTFE",
          "silicone"
        ],
        "avoidMaterials": [
          "polyurethane"
        ],
        "preparationNotes": [
          "Component system - mix per manufacturer instructions",
          "DMSO-compatible equipment required"
        ],
        "polymerizationTime": "1-3 minutes",
        "injectionPressure_psi": 50,
        "notes": "Faster polymerization than Onyx; less clinical experience"
      }
    ],
