  "pediatricGuidelines": {
    "version": "1.0",
    "considerations": [
      "Vessel diameter: Neonates 2-3mm; infants 3-4mm; small children 4-6mm",
      "Pressure limits: 200 psi max (adult: 300 psi) to prevent vessel rupture",
      "Access sites: Umbilical (neonatal), femoral (infants/children), radial (small children)",
      "Anticoagulation: Weight-based heparin dosing (75-100 U/kg bolus, 18-25 U/kg/hr drip)",
      "Anesthesia coordination: NPO status, sedation vs. general anesthesia per institutional protocol",
      "Congenital lesions: PDA, AVM, arteriovenous malformations common in pediatric IR",
      "Vessel compliance: Higher risk of vasospasm; avoid aggressive pressure/manipulation",
      "Radiation protection: ALARA principles; shorter fluoroscopy times, higher frame rates",
      "Family communication: Informed consent including growth considerations for implanted devices",
      "Long-term surveillance: Follow-up imaging for device position, stenosis, thrombosis"
    ]
  }
